-- =====================================================================
-- Lot 200 — 700 alias poses, 9 retires, 79 repointes
--
-- Une carte regroupee n'est pas une carte perdue : sa fonction est reprise
-- par une autre, et son ancienne adresse doit continuer d'y mener. Les
-- alias sont poses AVANT les retraits du lot 300, pour qu'aucun favori ni
-- aucun lien ne pende, meme une seconde.
--
-- MAIS LA BASE PORTE DEJA UNE CARTE DE REDIRECTIONS, ecrite pour le
-- catalogue d'avant, et poser les nouvelles par-dessus sans la regarder
-- echoue — c'est arrive en production le 23 septembre 2026, sur
-- « prompt_aliases_sans_chaine ». Ce declencheur interdit qu'un alias
-- pointe
-- vers une carte qui est elle-meme un alias. Ce n'est pas une contrainte a
-- contourner : c'est elle qui garantit qu'une ancienne adresse mene en UN
-- saut a une fiche qui existe, plutot qu'a une chaine qui se perd.
--
-- Deux gestes la respectent, dans cet ordre :
--
--   9 liens dont la SOURCE est une carte que la V5 garde sont retires.
--   Ils disaient « cette carte renvoie ailleurs » ; elle est canonique
--   desormais, donc ils mentent.
--
--   79 liens dont la DESTINATION est une carte regroupee avancent d'un
--   cran, vers la cible qui reprend la fonction. L'ancienne adresse
--   continue de mener quelque part, toujours en un saut.
--
-- Les 43 autres ne bougent pas. Ceux dont la destination part sans cible
-- cessent simplement de resoudre : leur source s'archive, et la page
-- d'archive dit ce qui s'est passe.
--
-- Un alias ne promet pas un resultat identique : il ouvre la bonne fiche.
-- =====================================================================

begin;

-- 1. Les liens que la refonte rend faux.
create temporary table v5_alias_perime (source uuid) on commit drop;
insert into v5_alias_perime select (x ->> 'source')::uuid
from jsonb_array_elements($raccourcia$[{"destination":"1cbaede2-172f-4d8c-bfa0-87b3e4f6e724","source":"365aa137-3619-4575-8a13-acc0ff7567ad"},{"destination":"1cbaede2-172f-4d8c-bfa0-87b3e4f6e724","source":"7ca986bc-12c0-48b6-8b65-57bb06b5dce1"},{"destination":"0aef6ad3-486d-48ee-bdea-bc6b15340432","source":"7dcca00b-520e-4ed0-8aba-254efe85f193"},{"destination":"efbaedc2-08a8-442b-8a8f-55dc83796bb6","source":"8edc4043-d451-49f3-b134-32fb2459bd6a"},{"destination":"ba2e4267-43bd-4007-844e-76468222b9ff","source":"b109e217-74be-4f29-96b6-90fe8f895ca0"},{"destination":"2515125b-150c-411a-9fc4-28f261699fa9","source":"b894c0d4-1163-4695-a33b-934efafbe648"},{"destination":"0aef6ad3-486d-48ee-bdea-bc6b15340432","source":"ced63a5c-852a-4307-9649-cc7ee17216e4"},{"destination":"2515125b-150c-411a-9fc4-28f261699fa9","source":"d8d11cd2-2a0e-4f8a-9a4d-5eecc9b5af7b"},{"destination":"0aef6ad3-486d-48ee-bdea-bc6b15340432","source":"e49592ab-3675-4459-a350-b9c6e5207055"}]$raccourcia$) x;

delete from public.prompt_aliases a using v5_alias_perime p
where a.alias_prompt_id = p.source;

do $ctrl$
begin
  if not ((select count(*) from public.prompt_aliases a join v5_alias_perime p
        on p.source = a.alias_prompt_id) = 0) then
    raise exception 'Lot 200 : un alias perime subsiste, il fera echouer les insertions.';
  end if;
end $ctrl$;

-- 2. Les liens qui menaient a une carte regroupee avancent d'un cran.
create temporary table v5_alias_repointe (source uuid, ancienne uuid, nouvelle uuid)
  on commit drop;
insert into v5_alias_repointe
