update public.prompt_aliases a
set canonical_prompt_id = r.nouvelle, updated_at = now()
from v5_alias_repointe r
where a.alias_prompt_id = r.source and a.canonical_prompt_id = r.ancienne;

do $ctrl$
begin
  if not (not exists (select 1 from public.prompt_aliases a join v5_alias_repointe r
            on r.source = a.alias_prompt_id
            where a.canonical_prompt_id = r.ancienne)) then
    raise exception 'Lot 200 : un alias pointe encore vers une carte regroupee.';
  end if;
end $ctrl$;

