insert into public.prompt_aliases (alias_prompt_id, canonical_prompt_id)
select a.alias, a.vers from v5_alias a
where exists (select 1 from public.prompts p where p.id = a.alias)
  and exists (select 1 from public.prompts p where p.id = a.vers)
-- alias_prompt_id est unique : une carte ne redirige que vers une
-- seule autre. 71 des 700 en portaient deja un, ecrit pour le catalogue
-- d'avant. La decision V5 l'emporte — c'est le choix editorial le plus
-- recent, et il designe une carte qui survit, la ou l'ancienne cible
-- s'archive peut-etre. « do nothing » les aurait sautees en silence,
-- et c'est exactement ce qui est arrive au premier essai.
on conflict (alias_prompt_id) do update
  set canonical_prompt_id = excluded.canonical_prompt_id, updated_at = now();

do $ctrl$
begin
  if not ((select count(*) from public.prompt_aliases pa join v5_alias a
        on a.alias = pa.alias_prompt_id and a.vers = pa.canonical_prompt_id) = 700) then
    raise exception 'Lot 200 : les 700 alias de regroupement ne sont pas tous poses.';
  end if;
end $ctrl$;

do $ctrl$
begin
  if not (not exists (select 1 from public.prompt_aliases pa join v5_alias a on a.alias = pa.alias_prompt_id
            where pa.alias_prompt_id = pa.canonical_prompt_id)) then
    raise exception 'Lot 200 : un alias pointe sur lui-meme.';
  end if;
end $ctrl$;

commit;
